<template>
  <div class="app">
    <!-- Password recovery modal — always on top, bypasses gate -->
    <transition name="modal-fade">
      <div v-if="showRecoveryModal" class="recovery-overlay">
        <div class="recovery-modal">
          <div class="recovery-title">איפוס סיסמה</div>
          <input
            v-model="recoveryPassword"
            type="password"
            class="recovery-input"
            placeholder="סיסמה חדשה"
            autocomplete="new-password"
          />
          <input
            v-model="recoveryConfirm"
            type="password"
            class="recovery-input"
            placeholder="אימות סיסמה"
            autocomplete="new-password"
            @keyup.enter="submitRecovery"
          />
          <div v-if="recoveryError" class="recovery-error">{{ recoveryError }}</div>
          <div v-if="recoverySuccess" class="recovery-success">הסיסמה עודכנה בהצלחה!</div>
          <div class="recovery-btns">
            <button class="recovery-btn-ok" @click="submitRecovery" :disabled="recoveryLoading || recoverySuccess">
              {{ recoveryLoading ? '...' : 'שמור סיסמה' }}
            </button>
          </div>
        </div>
      </div>
    </transition>

    <div v-if="!authChecked" class="app-loading"></div>
    <site-password v-else-if="showGate" @verified="onVerified" />
    <template v-else>
      <open-page v-if="page===-1" @homePage="homePage"></open-page>
      <home-page v-if="page===0" @chosenNum="nextPage"></home-page>
      <text-page v-if="page===1" @back="back" :tabNum="chosenTab"></text-page>
    </template>
  </div>
</template>

<script>
import OpenPage from "@/components/OpenPage";
import HomePage from "@/components/HomePage";
import TextPage from "@/components/TextPage";
import SitePassword from "@/components/SitePassword";
import { supabase } from "@/supabase";

export default {
  name: "App",
  components: {
    HomePage,
    TextPage,
    OpenPage,
    SitePassword,
  },
  data() {
    return {
      page: -1,
      chosenTab: -1,
      authChecked: false,
      siteVerified: false,
      sitePasswordSet: false,
      adminSession: null,
      // Password recovery
      showRecoveryModal: false,
      recoveryPassword: "",
      recoveryConfirm: "",
      recoveryError: "",
      recoverySuccess: false,
      recoveryLoading: false,
    };
  },
  computed: {
    showGate() {
      return this.sitePasswordSet && !this.siteVerified && !this.adminSession;
    },
  },
  async mounted() {
    // Subscribe before getSession so PASSWORD_RECOVERY is never missed
    supabase.auth.onAuthStateChange((event, session) => {
      this.adminSession = session;
      if (event === 'PASSWORD_RECOVERY') {
        this.recoveryPassword = "";
        this.recoveryConfirm  = "";
        this.recoveryError    = "";
        this.recoverySuccess  = false;
        this.showRecoveryModal = true;
      }
      if (event === 'SIGNED_OUT') {
        this.adminSession = null;
      }
    });

    const [{ data: { session } }, { data: settingsData }] = await Promise.all([
      supabase.auth.getSession(),
      supabase.from('site_settings').select('value').eq('key', 'site_password_hash').maybeSingle(),
    ]);

    this.adminSession    = session;
    this.sitePasswordSet = !!(settingsData && settingsData.value);
    this.siteVerified    = sessionStorage.getItem('site_verified') === 'true';
    this.authChecked     = true;
  },
  methods: {
    async submitRecovery() {
      this.recoveryError = "";
      if (this.recoveryPassword.length < 6) {
        this.recoveryError = "הסיסמה חייבת להכיל לפחות 6 תווים";
        return;
      }
      if (this.recoveryPassword !== this.recoveryConfirm) {
        this.recoveryError = "הסיסמאות אינן תואמות";
        return;
      }
      this.recoveryLoading = true;
      const { error } = await supabase.auth.updateUser({ password: this.recoveryPassword });
      this.recoveryLoading = false;
      if (error) {
        this.recoveryError = "שגיאה בעדכון הסיסמה, נסה שוב";
      } else {
        this.recoverySuccess = true;
        window.history.replaceState(null, '', window.location.pathname);
        setTimeout(() => { this.showRecoveryModal = false; }, 1500);
      }
    },
    onVerified() {
      this.siteVerified = true;
    },
    nextPage(chosenNum) {
      this.chosenTab = chosenNum;
      this.page++;
    },
    back() {
      this.page = 0;
    },
    homePage() {
      this.page = 0;
    },
  },
};
</script>

